    for i in range(1, n + 1):
        yield i * i

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

def limpar(linhas):
    for l in linhas:
        l = l.strip()
        if l:
            yield l

