import time
def cronometro(func):
    def wrapper(*args, **kwargs):
        ini = time.time()
        res = func(*args, **kwargs)
        print(f"{func.__name__}: {time.time()-ini:.3f}s")
        return res
    return wrapper

@cronometro
def processar():
    return sum(range(1_000_000))

